    static Object displayIngredient(JsonObject value){if(value.has("item"))return stack(value.get("item").getAsString());String tag=value.get("tag").getAsString();List<String> examples=switch(tag){case "forge:travellers_gear/cloaks"->List.of("witchinggadgets:cloak_standard","witchinggadgets:cloak_plain");case "minecraft:planks"->List.of("minecraft:oak_planks","minecraft:spruce_planks","thaumcraft:greatwood_planks");case "forge:shards","thaumcraft:shards"->List.of("thaumcraft:air_shard","thaumcraft:fire_shard","thaumcraft:water_shard","thaumcraft:earth_shard","thaumcraft:order_shard","thaumcraft:entropy_shard");default->List.of();};return map("kind","ore","names",List.of("#"+tag),"elements",examples.stream().map(WGData::stack).toList());}
    void arcane(CachedOutput cache,List<CompletableFuture<?>> jobs,String id,String research,String result,int count,Map<String,Integer> vis,List<String> pattern,Map<String,Object> key,String... requiredMods){
        var definition=map("type","thaumcraft:arcane","research","witchinggadgets:"+research,"mode","shaped","vis",vis,"pattern",pattern,"key",key,"result",map("item",result,"count",count));if(id.startsWith("kama_"))definition.put("result_transform",map("type","witchinggadgets:cloak_to_kama"));if(requiredMods.length>0)definition.put("conditions",Arrays.stream(requiredMods).map(mod->map("type","forge:mod_loaded","modid",mod)).toList());jobs.add(save(cache,"data/witchinggadgets/recipes/"+id+".json",definition));
        var inputs=new ArrayList<Object>();for(String row:pattern)for(char c:row.toCharArray()){if(c==' ')inputs.add(map("kind","sequence","elements",List.of()));else inputs.add(displayIngredient(JSON.toJsonTree(key.get(""+c)).getAsJsonObject()));}
        display.add(map("key","witchinggadgets:"+id,"class","modern","data",map("kind","arcane_shaped","research","witchinggadgets:"+research,"output",map("kind","stack","stack",map("item",result,"count",count)),"ingredients",sequence(inputs),"aspects",vis,"width",pattern.get(0).length(),"height",pattern.size())));
    }
